// Extracts package installs from raw run_commands inputs.
// Hooks see the raw model input, so we handle every accepted shape.
// Shapes from docs/sdk-facts.md:
//   { commands: string[] }, { commands: string }, { command: string },
//   { cmd: string }, { command, args }, a bare string, or an array.

export type InstallRequest = {
  registry: "pypi" | "npm";
  name: string; // Normalized package name.
  raw: string; // The token as typed, for messages.
};

// Collect every command string from any accepted input shape.
export function extractCommandStrings(input: unknown): string[] {
  if (typeof input === "string") return [input];
  if (Array.isArray(input)) {
    return input.flatMap((item) => extractCommandStrings(item));
  }
  if (input && typeof input === "object") {
    const record = input as Record<string, unknown>;
    if (Array.isArray(record.commands)) return record.commands.flatMap((c) => extractCommandStrings(c));
    if (typeof record.commands === "string") return [record.commands];
    if (typeof record.command === "string") {
      const args = Array.isArray(record.args) ? record.args.join(" ") : "";
      return [args ? `${record.command} ${args}` : record.command];
    }
    if (typeof record.cmd === "string") return [record.cmd];
  }
  return [];
}

// Split one command string into segments on &&, ;, ||, |.
function splitSegments(command: string): string[] {
  return command.split(/&&|\|\||[;|]/).map((part) => part.trim()).filter(Boolean);
}

// Strip version specifiers and extras: "flask==3.0" -> "flask", "uvicorn[standard]" -> "uvicorn".
function cleanName(token: string): string {
  return token.split(/[=<>!~[\]]/)[0].trim();
}

function isFlag(token: string): boolean {
  return token.startsWith("-");
}

// Normalize a PyPI name: lowercase, runs of -_. become -.
function normalizePypi(name: string): string {
  return name.toLowerCase().replace(/[-_.]+/g, "-");
}

function parsePipInstall(words: string[], raw: string): InstallRequest[] {
  const found: InstallRequest[] = [];
  for (const word of words) {
    if (isFlag(word)) continue;
    const name = cleanName(word);
    if (!name) continue;
    found.push({ registry: "pypi", name: normalizePypi(name), raw });
  }
  return found;
}

function parseNpmInstall(words: string[], raw: string): InstallRequest[] {
  const found: InstallRequest[] = [];
  for (const word of words) {
    if (isFlag(word)) continue;
    // Strip npm version/tag suffix, but keep the @scope prefix.
    const name = word.startsWith("@") ? word : word.split("@")[0];
    const cleaned = cleanName(name);
    if (!cleaned) continue;
    found.push({ registry: "npm", name: cleaned.toLowerCase(), raw });
  }
  return found;
}

// Find all install commands in one segment.
function parseSegment(segment: string): InstallRequest[] {
  const words = segment.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];

  // pip install flask | pip3 install flask | python -m pip install flask | python3 -m pip install flask
  let pipWords: string[] | null = null;
  if ((words[0] === "pip" || words[0] === "pip3") && words[1] === "install") {
    pipWords = words.slice(2);
  } else if (
    (words[0] === "python" || words[0] === "python3") &&
    words[1] === "-m" && words[2] === "pip" && words[3] === "install"
  ) {
    pipWords = words.slice(4);
  }
  if (pipWords) return parsePipInstall(pipWords, segment);

  // npm install react | npm i react | pnpm add react | yarn add react
  if (words[0] === "npm" && (words[1] === "install" || words[1] === "i")) {
    return parseNpmInstall(words.slice(2), segment);
  }
  if ((words[0] === "pnpm" || words[0] === "yarn") && words[1] === "add") {
    return parseNpmInstall(words.slice(2), segment);
  }

  return [];
}

// Main entry: all install requests in a raw run_commands input.
export function findInstalls(input: unknown): InstallRequest[] {
  const commands = extractCommandStrings(input);
  return commands.flatMap((command) => splitSegments(command).flatMap(parseSegment));
}

// Detect "curl ... | sh" and "wget ... | sh" style pipes. Hard block per spec.
export function hasCurlPipeSh(input: unknown): boolean {
  return extractCommandStrings(input).some((command) =>
    /\b(curl|wget)\b[^|]*\|\s*(sudo\s+)?(ba)?sh\b/.test(command)
  );
}

// Checks package names against PyPI and npm.
// Every call has a 2500 ms timeout. Network failure means status "unknown", never a block.

export type RegistryStatus = "exists" | "missing" | "unknown";

export type RegistryCheck = {
  status: RegistryStatus;
  ageDays?: number; // Days since the first release.
  releaseCount?: number;
  suggestion?: string; // "did you mean X" from the popular list.
};

const TIMEOUT_MS = 2500;

// About 30 popular names per registry, for typo warnings.
const POPULAR_PYPI = [
  "flask", "django", "fastapi", "requests", "numpy", "pandas", "scipy", "sqlalchemy",
  "celery", "pytest", "click", "boto3", "pillow", "matplotlib", "scikit-learn", "torch",
  "transformers", "openai", "anthropic", "pydantic", "uvicorn", "gunicorn", "aiohttp",
  "httpx", "redis", "pymongo", "psycopg2", "cryptography", "beautifulsoup4", "lxml",
  "jinja2", "werkzeug", "tqdm", "rich", "typer", "starlette",
];

const POPULAR_NPM = [
  "react", "react-dom", "vue", "angular", "svelte", "next", "express", "fastify",
  "lodash", "axios", "moment", "dayjs", "chalk", "commander", "typescript", "webpack",
  "vite", "eslint", "prettier", "jest", "vitest", "mocha", "zod", "yup", "prisma",
  "mongoose", "pg", "mysql2", "redis", "socket.io", "tailwindcss", "postcss", "dotenv",
  "cors", "helmet", "jsonwebtoken", "bcrypt",
];

// Levenshtein distance, for typo detection.
export function editDistance(a: string, b: string): number {
  const rows = a.length + 1;
  const cols = b.length + 1;
  const grid: number[][] = Array.from({ length: rows }, (_, i) => [i, ...Array(cols - 1).fill(0)]);
  for (let j = 0; j < cols; j++) grid[0][j] = j;
  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < cols; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      grid[i][j] = Math.min(grid[i - 1][j] + 1, grid[i][j - 1] + 1, grid[i - 1][j - 1] + cost);
    }
  }
  return grid[a.length][b.length];
}

// Find a "did you mean" suggestion. Distance 1 always counts. Distance 2 counts for longer names.
export function findSuggestion(name: string, popular: string[]): string | undefined {
  let best: string | undefined;
  let bestDistance = Infinity;
  for (const candidate of popular) {
    if (candidate === name) return undefined; // The name itself is popular. Not a typo.
    const distance = editDistance(name, candidate);
    const allowed = candidate.length >= 5 ? 2 : 1;
    if (distance <= allowed && distance < bestDistance) {
      best = candidate;
      bestDistance = distance;
    }
  }
  return best;
}

async function fetchJson(url: string): Promise<{ ok: boolean; status: number; body?: unknown }> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const response = await fetch(url, { signal: controller.signal });
    if (response.status === 404) return { ok: false, status: 404 };
    if (!response.ok) return { ok: false, status: response.status };
    return { ok: true, status: response.status, body: await response.json() };
  } finally {
    clearTimeout(timer);
  }
}

function daysSince(isoDate: string): number {
  const ms = Date.now() - new Date(isoDate).getTime();
  return Math.floor(ms / 86_400_000);
}

async function checkPypi(name: string): Promise<RegistryCheck> {
  const suggestion = findSuggestion(name, POPULAR_PYPI);
  try {
    const result = await fetchJson(`https://pypi.org/pypi/${encodeURIComponent(name)}/json`);
    if (result.status === 404) return { status: "missing", suggestion };
    if (!result.ok) return { status: "unknown", suggestion };
    const body = result.body as { releases?: Record<string, { upload_time?: string }[]> };
    const releases = body.releases ?? {};
    const releaseCount = Object.keys(releases).length;
    let oldest: number | undefined;
    for (const files of Object.values(releases)) {
      for (const file of files) {
        if (!file.upload_time) continue;
        const time = new Date(file.upload_time).getTime();
        if (oldest === undefined || time < oldest) oldest = time;
      }
    }
    const ageDays = oldest === undefined ? undefined : Math.floor((Date.now() - oldest) / 86_400_000);
    return { status: "exists", ageDays, releaseCount, suggestion };
  } catch {
    return { status: "unknown", suggestion };
  }
}

async function checkNpm(name: string): Promise<RegistryCheck> {
  const suggestion = findSuggestion(name, POPULAR_NPM);
  try {
    // Scoped names need the slash encoded: @scope/name -> @scope%2Fname.
    const encoded = name.startsWith("@") ? name.replace("/", "%2F") : name;
    const result = await fetchJson(`https://registry.npmjs.org/${encoded}`);
    if (result.status === 404) return { status: "missing", suggestion };
    if (!result.ok) return { ok: false as never, status: "unknown", suggestion };
    const body = result.body as { time?: Record<string, string> };
    const time = body.time ?? {};
    const created = time.created;
    const releaseCount = Math.max(0, Object.keys(time).length - 2); // Minus created and modified.
    const ageDays = created ? daysSince(created) : undefined;
    return { status: "exists", ageDays, releaseCount, suggestion };
  } catch {
    return { status: "unknown", suggestion };
  }
}

// In-memory cache for one run. The same package is never checked twice.
const cache = new Map<string, RegistryCheck>();

export async function checkPackage(registry: "pypi" | "npm", name: string): Promise<RegistryCheck> {
  const key = `${registry}:${name}`;
  const cached = cache.get(key);
  if (cached) return cached;
  const check = registry === "pypi" ? await checkPypi(name) : await checkNpm(name);
  cache.set(key, check);
  return check;
}

