// Shared finding shape. The scan writes findings. The fix step updates them.
// The teacher reads them. It never invents new ones.

export type Finding = {
  id: string; // Stable id, like "bandit-B608-app.py-42" or "custom-missing-env-gitignore".
  severity: "high" | "medium" | "low";
  title: string; // One line.
  file?: string; // Path relative to demo-app/.
  line?: number;
  source: "bandit" | "custom";
  detail: string;
  status: "open" | "fixed";
};

import { execFile } from "node:child_process";
import { readFile, readdir } from "node:fs/promises";
import { join, relative } from "node:path";
import { promisify } from "node:util";
import { checkPackage } from "./lib/registry.js";
import { appendEvent, demoAppDir, writeJson } from "./lib/store.js";
import type { Finding } from "./lib/findings.js";

// Scans the demo app after the build.
// Bandit finds real Python issues. Custom checks cover what bandit misses.
// Writes data/findings.json and appends one event per finding.

const run = promisify(execFile);

type BanditResult = {
  filename: string;
  line_number: number;
  issue_severity: "LOW" | "MEDIUM" | "HIGH";
  issue_text: string;
  test_id: string;
  test_name: string;
};

function banditSeverity(level: string): Finding["severity"] {
  if (level === "HIGH") return "high";
  if (level === "MEDIUM") return "medium";
  return "low";
}

async function runBandit(): Promise<Finding[]> {
  try {
    // Bandit exits 1 when it finds issues. That is normal, not an error.
    const { stdout } = await run(
      "python3",
      ["-m", "bandit", "-r", "demo-app", "-x", "demo-app/venv", "-f", "json"],
      { cwd: demoAppDir + "/..", maxBuffer: 16 * 1024 * 1024 }
    );
    const parsed = JSON.parse(stdout) as { results?: BanditResult[] };
    return (parsed.results ?? []).map((result) => ({
      id: `bandit-${result.test_id}-${relative(demoAppDir, result.filename)}-${result.line_number}`,
      severity: banditSeverity(result.issue_severity),
      title: result.issue_text,
      file: relative(demoAppDir, result.filename),
      line: result.line_number,
      source: "bandit" as const,
      detail: `${result.test_id} ${result.test_name}`,
      status: "open" as const,
    }));
  } catch (error) {
    // execFile rejects on exit code 1. The JSON is still on stdout.
    const stdout = (error as { stdout?: string }).stdout;
    if (stdout) {
      try {
        const parsed = JSON.parse(stdout) as { results?: BanditResult[] };
        return (parsed.results ?? []).map((result) => ({
          id: `bandit-${result.test_id}-${relative(demoAppDir, result.filename)}-${result.line_number}`,
          severity: banditSeverity(result.issue_severity),
          title: result.issue_text,
          file: relative(demoAppDir, result.filename),
          line: result.line_number,
          source: "bandit" as const,
          detail: `${result.test_id} ${result.test_name}`,
          status: "open" as const,
        }));
      } catch {
        // Fall through to the error event below.
      }
    }
    console.error("[scan] bandit failed:", error);
    return [];
  }
}

// Custom check 1: every package in requirements.txt must exist on PyPI.
async function checkRequirements(): Promise<Finding[]> {
  const findings: Finding[] = [];
  let text: string;
  try {
    text = await readFile(join(demoAppDir, "requirements.txt"), "utf8");
  } catch {
    return findings; // No requirements file, nothing to check.
  }
  for (const line of text.split("\n")) {
    const name = line.split(/[=<>!~;\s]/)[0].trim();
    if (!name || name.startsWith("#") || name.startsWith("-")) continue;
    const check = await checkPackage("pypi", name.toLowerCase().replace(/[-_.]+/g, "-"));
    if (check.status === "missing") {
      findings.push({
        id: `custom-missing-package-${name}`,
        severity: "high",
        title: `Package "${name}" in requirements.txt does not exist on PyPI`,
        file: "requirements.txt",
        source: "custom",
        detail: check.suggestion ? `Did you mean "${check.suggestion}"?` : "The agent invented this name.",
        status: "open",
      });
    }
  }
  return findings;
}

// Custom check 2: .env must be in .gitignore.
async function checkGitignore(): Promise<Finding[]> {
  try {
    const text = await readFile(join(demoAppDir, ".gitignore"), "utf8");
    const lines = text.split("\n").map((line) => line.trim());
    if (lines.includes(".env")) return [];
  } catch {
    // No .gitignore at all is also a finding.
  }
  return [{
    id: "custom-env-not-gitignored",
    severity: "medium",
    title: ".env is not excluded by .gitignore. Secrets could be committed.",
    file: ".gitignore",
    source: "custom",
    detail: "Add a line with .env to demo-app/.gitignore.",
    status: "open",
  }];
}

// Custom check 3: no hard-coded SECRET_KEY in Python files.
async function checkSecretKey(): Promise<Finding[]> {
  const findings: Finding[] = [];
  const entries = await readdir(demoAppDir, { withFileTypes: true, recursive: true });
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith(".py")) continue;
    const path = join(entry.parentPath, entry.name);
    if (path.includes("venv")) continue;
    const text = await readFile(path, "utf8");
    const lines = text.split("\n");
    lines.forEach((line, index) => {
      if (/SECRET_KEY\s*=\s*["'][^"']+["']/.test(line)) {
        findings.push({
          id: `custom-hardcoded-secret-${entry.name}-${index + 1}`,
          severity: "high",
          title: "Hard-coded SECRET_KEY in code. It belongs in .env.",
          file: relative(demoAppDir, path),
          line: index + 1,
          source: "custom",
          detail: "Read the secret key from an environment variable.",
          status: "open",
        });
      }
    });
  }
  return findings;
}

const findings: Finding[] = [
  ...(await runBandit()),
  ...(await checkRequirements()),
  ...(await checkGitignore()),
  ...(await checkSecretKey()),
];

await writeJson("findings", { findings });
for (const finding of findings) {
  await appendEvent({
    ts: new Date().toISOString(), source: "scan", kind: "finding",
    summary: `[${finding.severity.toUpperCase()}] ${finding.title}`,
    detail: { ...finding },
  });
}
console.log(`Scan complete: ${findings.length} findings (${findings.filter((f) => f.severity === "high").length} high).`);

import { Agent, createTool } from "@cline/sdk";
import { z } from "zod";
import { getClinePassKey } from "./auth.js";
import type { Decision } from "../plugin/guard.js";
import type { Finding } from "./findings.js";

// The teacher is an SDK Agent. It never invents findings.
// It explains real findings and real decisions, against the real code.
// Structured output comes from a submit tool with completesRun. No JSON parsing.

export type Lesson = {
  id: string;
  title: string;
  risk_level: "high" | "medium" | "low";
  security: boolean; // Security lessons weigh double in the score.
  body: string; // The lesson text. Plain words. Short sentences.
  file_refs: { path: string; lines: string }[]; // Example: { path: "app.py", lines: "40-48" }.
  reason_check: string; // Does the agent's logged reason match the code? Say how.
  question: string; // The explain-back question for the user.
};

export type Grade = {
  score: number; // 0 to 100.
  got_right: string[];
  missed: string[];
};

const LESSON_MODEL = process.env.TEACHER_MODEL ?? "cline-pass/deepseek-v4.1-flash";
const GRADER_MODEL = process.env.GRADER_MODEL ?? "cline-pass/deepseek-v4-pro";

const STYLE = `Writing rules:
- One fact per sentence. Sentences under 20 words.
- Explain like the reader has never seen the concept. Define every term.
- Reference real file names and line numbers from the code given to you.`;

// Generate lessons from the real build data.
export async function generateLessons(input: {
  decisions: Decision[];
  findings: Finding[];
  source: string; // Concatenated demo-app source with file names.
}): Promise<Lesson[]> {
  let submitted: Lesson[] | undefined;

  const submitTool = createTool({
    name: "submit_lessons",
    description: "Submit the final lessons. This ends your run.",
    inputSchema: z.object({
      lessons: z.array(
        z.object({
          id: z.string(),
          title: z.string(),
          risk_level: z.enum(["high", "medium", "low"]),
          security: z.boolean(),
          body: z.string(),
          file_refs: z.array(z.object({ path: z.string(), lines: z.string() })),
          reason_check: z.string(),
          question: z.string(),
        })
      ),
    }),
    lifecycle: { completesRun: true },
    execute: async (input: { lessons: Lesson[] }) => {
      submitted = input.lessons;
      return { ok: true };
    },
  });

  const apiKey = await getClinePassKey(); // Fresh key each run. Never cached.
  const agent = new Agent({
    providerId: "cline-pass",
    modelId: LESSON_MODEL,
    apiKey,
    systemPrompt: `You are the Grasper teacher. You teach a beginner the app their AI agent built.
${STYLE}
Rules:
- Write one lesson per high or medium finding, riskiest first.
- Then up to three lessons for the biggest decisions (framework, database, auth).
- Each lesson has a reason_check line: compare the agent's logged reason with the real code.
- Each lesson ends with one explain-back question the user must answer in their own words.
- Call submit_lessons at the end. Do not answer in plain text.`,
    tools: [submitTool],
    maxIterations: 8,
  });

  const prompt = `Here is the app, the decisions, and the scan findings.

## Decisions logged during the build
${input.decisions.map((d) => `- ${d.topic} = ${d.choice}: ${d.reason}${d.inferred ? " (inferred, reason not stated)" : ""}`).join("\n") || "(none)"}

## Scan findings
${input.findings.map((f) => `- [${f.severity}] ${f.title} (${f.source}${f.file ? `, ${f.file}${f.line ? `:${f.line}` : ""}` : ""})`).join("\n") || "(none)"}

## App source
${input.source}

Write the lessons now. Call submit_lessons when done.`;

  const result = await agent.run(prompt);
  if (!submitted) {
    console.error("[teacher] no lessons submitted. status:", result.status, "output:", result.outputText);
    throw new Error("Teacher did not submit lessons.");
  }
  return submitted;
}

// Grade one explain-back answer against the real code. Security points count most.
export async function gradeExplainBack(input: {
  lesson: Lesson;
  answer: string;
  source: string;
}): Promise<Grade> {
  let submitted: Grade | undefined;

  const submitTool = createTool({
    name: "submit_grade",
    description: "Submit the final grade. This ends your run.",
    inputSchema: z.object({
      score: z.number().min(0).max(100),
      got_right: z.array(z.string()),
      missed: z.array(z.string()),
    }),
    lifecycle: { completesRun: true },
    execute: async (input: Grade) => {
      submitted = input;
      return { ok: true };
    },
  });

  const apiKey = await getClinePassKey();
  const agent = new Agent({
    providerId: "cline-pass",
    modelId: GRADER_MODEL,
    apiKey,
    systemPrompt: `You are the Grasper grader. You grade a beginner's explanation of their own app.
${STYLE}
Rules:
- Grade the answer against the real code, not against the lesson text.
- Security understanding counts most. A wrong security claim caps the score at 40.
- got_right and missed list short, concrete points.
- Call submit_grade at the end. Do not answer in plain text.`,
    tools: [submitTool],
    maxIterations: 6,
  });

  const prompt = `Lesson: ${input.lesson.title}
Question: ${input.lesson.question}

The user's answer:
${input.answer}

The real code:
${input.source}

Grade the answer. Call submit_grade when done.`;

  const result = await agent.run(prompt);
  if (!submitted) {
    console.error("[teacher] no grade submitted. status:", result.status, "output:", result.outputText);
    throw new Error("Grader did not submit a grade.");
  }
  return submitted;
}

