 33 | // Levenshtein distance, for typo detection.
 34 | export function editDistance(a: string, b: string): number {
 35 |   const rows = a.length + 1;
 36 |   const cols = b.length + 1;
 37 |   const grid: number[][] = Array.from({ length: rows }, (_, i) => [i, ...Array(cols - 1).fill(0)]);
 38 |   for (let j = 0; j < cols; j++) grid[0][j] = j;
 39 |   for (let i = 1; i < rows; i++) {
 40 |     for (let j = 1; j < cols; j++) {
 41 |       const cost = a[i - 1] === b[j - 1] ? 0 : 1;
 42 |       grid[i][j] = Math.min(grid[i - 1][j] + 1, grid[i][j - 1] + 1, grid[i - 1][j - 1] + cost);
 43 |     }
 44 |   }
 45 |   return grid[a.length][b.length];
 46 | }
