 54 |     const distance = editDistance(name, candidate);
 55 |     const allowed = candidate.length >= 5 ? 2 : 1;
 56 |     if (distance <= allowed && distance < bestDistance) {
 57 |       best = candidate;
 58 |       bestDistance = distance;
 59 |     }
