import assert from "node:assert/strict";

// Timing test for the BUNDLED app-mode plugin (cline-plugin/grasper.js).
// The Cline app sandbox gives hooks a hard 3000 ms. Every case must finish
// under 2500 ms. Prints each time.

const LIMIT_MS = 2500;

// Import the built bundle. Data dir comes from GRASPER_DATA_DIR (set by npm test).
const { plugin, default: defaultExport } = await import("../../cline-plugin/grasper.js");
assert.ok(plugin?.hooks?.beforeTool, "bundled plugin must expose beforeTool");
assert.equal(defaultExport, plugin, "default export must be the same plugin object");

const beforeTool = plugin.hooks.beforeTool as (context: unknown) => Promise<unknown>;

type Case = { name: string; toolName: string; input: unknown };

const cases: Case[] = [
  { name: "fake package", toolName: "run_commands", input: { commands: ["pip install flask-remember-secure-pro"] } },
  { name: "real package", toolName: "run_commands", input: { commands: ["pip install flask"] } },
  {
    name: "secret write",
    toolName: "editor",
    input: { path: "/app/config.py", new_text: 'OPENAI_KEY = "sk-proj-AbCdEfGhIjKlMnOpQrStUvWxYz123456"\n' },
  },
];

for (const testCase of cases) {
  const start = Date.now();
  const result = (await beforeTool({
    toolCall: { toolCallId: "t", toolName: testCase.toolName, input: testCase.input },
    input: testCase.input,
    snapshot: {},
    tool: {},
  })) as { skip?: boolean; reason?: string };
  const ms = Date.now() - start;
  console.log(`${testCase.name}: ${ms} ms -> ${result?.skip ? "blocked" : "allowed/warned"}`);
  assert.ok(ms < LIMIT_MS, `${testCase.name} took ${ms} ms, limit is ${LIMIT_MS} ms`);
}

// Unreachable registry: make every fetch reject, then install an uncached package.
const realFetch = globalThis.fetch;
globalThis.fetch = (() => Promise.reject(new TypeError("simulated network failure"))) as typeof fetch;
try {
  const start = Date.now();
  const result = (await beforeTool({
    toolCall: { toolCallId: "t2", toolName: "run_commands", input: { commands: ["pip install python-dotenv"] } },
    input: { commands: ["pip install python-dotenv"] },
    snapshot: {},
    tool: {},
  })) as { skip?: boolean; appendContext?: string };
  const ms = Date.now() - start;
  console.log(`unreachable registry: ${ms} ms -> ${result?.skip ? "blocked" : "allowed with warning"}`);
  assert.ok(ms < LIMIT_MS, `unreachable registry took ${ms} ms, limit is ${LIMIT_MS} ms`);
  assert.ok(!result?.skip, "unreachable registry must never block: fail open");
} finally {
  globalThis.fetch = realFetch;
}

console.log("ALL TIMING TESTS PASSED");

